const colors = { off: '#ffffff', heating: '#e24d42', cooling: '#5794f2' };
const temperaturePoints = [];
let unit = 'F';

for (const frame of context.panel.data.series) {
  const timeField = frame.fields.find((field) => field.type === 'time');
  const valueField = frame.fields.find((field) => field.type === 'number');
  if (!timeField || !valueField) continue;

  const times = timeField.values.buffer || timeField.values;
  const values = valueField.values.buffer || valueField.values;
  const labels = valueField.labels || {};
  if (labels.unit) unit = labels.unit;

  const equipment = labels.equipment || 'off';
  for (let index = 0; index < values.length; index += 1) {
    if (values[index] == null) continue;
    const time = Number(times[index]);
    const value = Number(values[index]);
    if (Number.isFinite(time) && Number.isFinite(value)) temperaturePoints.push({ time, value, equipment });
  }
}

temperaturePoints.sort((left, right) => left.time - right.time);
const segments = { off: [], heating: [], cooling: [] };
for (let index = 1; index < temperaturePoints.length; index += 1) {
  const start = temperaturePoints[index - 1];
  const end = temperaturePoints[index];
  if (end.time <= start.time || end.time - start.time > 120000) continue;
  if (segments[end.equipment]) segments[end.equipment].push([start.time, start.value, end.time, end.value]);
}

const temperatureSeries = Object.entries(segments).map(([equipment, data]) => ({
  name: equipment,
  type: 'custom',
  coordinateSystem: 'cartesian2d',
  clip: true,
  lineStyle: { color: colors[equipment], width: 2 },
  itemStyle: { color: colors[equipment] },
  dimensions: ['startTime', 'startTemperature', 'endTime', 'endTemperature'],
  encode: { x: [0, 2], y: [1, 3], tooltip: [0, 1, 2, 3] },
  data,
  renderItem: (params, api) => {
    const start = api.coord([api.value(0), api.value(1)]);
    const end = api.coord([api.value(2), api.value(3)]);
    return { type: 'line', shape: { x1: start[0], y1: start[1], x2: end[0], y2: end[1] }, style: { stroke: colors[equipment], lineWidth: 2 } };
  }
}));

return {
  backgroundColor: 'transparent',
  animation: false,
  grid: { left: 80, right: 30, top: 35, bottom: 55 },
  tooltip: { trigger: 'axis', axisPointer: { type: 'cross' } },
  color: ['#ffffff', '#e24d42', '#5794f2'],
  legend: { bottom: 0, data: Object.keys(segments), textStyle: { color: 'rgba(128, 128, 128, .9)' } },
  xAxis: { type: 'time', boundaryGap: false },
  yAxis: { type: 'value', name: 'Temperature (' + unit + ')', nameLocation: 'middle', nameGap: 55, scale: true, minInterval: 0.5, axisLabel: { formatter: (value) => Number(value).toFixed(1) }, splitLine: { lineStyle: { color: 'rgba(128, 128, 128, .18)' } } },
  series: temperatureSeries
};

const colors = { Low: '#b877d9', Normal: '#73bf69', High: '#f2cc0c', 'Setpoint unavailable': '#8e8e8e' };
const humidityPoints = [];

for (const frame of context.panel.data.series) {
  const timeField = frame.fields.find((field) => field.type === 'time');
  const valueField = frame.fields.find((field) => field.type === 'number');
  if (!timeField || !valueField) continue;

  const times = timeField.values.buffer || timeField.values;
  const values = valueField.values.buffer || valueField.values;
  const state = (valueField.labels || {}).state;
  if (state === undefined) continue;
  const dashed = (valueField.labels || {}).humidifier === 'off';

  for (let index = 0; index < values.length; index += 1) {
    if (values[index] == null) continue;
    const time = Number(times[index]);
    const value = Number(values[index]);
    if (Number.isFinite(time) && Number.isFinite(value)) humidityPoints.push({ time, value, state, dashed });
  }
}

// One continuous line: each segment takes the colour and dash style of the reading at its end point.
// Consecutive segments with the same style are merged so dashes run unbroken across readings.
humidityPoints.sort((left, right) => left.time - right.time);
const seriesInfo = [];
const groups = new Map();
for (const state of Object.keys(colors)) {
  for (const dashed of [false, true]) {
    const group = { state, dashed, data: [], lastTime: null };
    groups.set(state + '|' + dashed, group);
    seriesInfo.push(group);
  }
}

let last = null;
for (let index = 1; index < humidityPoints.length; index += 1) {
  const start = humidityPoints[index - 1];
  const end = humidityPoints[index];
  if (end.time <= start.time || end.time - start.time > 120000) continue;
  const key = end.state + '|' + end.dashed;
  const group = groups.get(key);
  if (!group) continue;
  if (!last || last.key !== key || last.index !== index - 1) {
    if (group.lastTime !== null) group.data.push([(group.lastTime + start.time) / 2, null]);
    group.data.push([start.time, start.value]);
  }
  group.data.push([end.time, end.value]);
  group.lastTime = end.time;
  last = { key, index };
}

const humiditySeries = seriesInfo.map((group) => ({
  name: group.state,
  type: 'line',
  showSymbol: false,
  connectNulls: false,
  lineStyle: { color: colors[group.state], width: 2, type: group.dashed ? 'dashed' : 'solid' },
  itemStyle: { color: colors[group.state] },
  data: group.data
}));

return {
  backgroundColor: 'transparent',
  animation: false,
  grid: { left: 80, right: 30, top: 35, bottom: 55 },
  tooltip: { trigger: 'axis', axisPointer: { type: 'cross' }, formatter: (params) => {
    const hits = params.filter((item) => item.value && item.value[1] != null);
    if (!hits.length) return '';
    return hits[0].axisValueLabel + '<br/>' + hits.map((item) => item.marker + item.seriesName + ': ' + Number(item.value[1]).toFixed(1) + '%' + (seriesInfo[item.seriesIndex].dashed ? ' (humidifier off)' : '')).join('<br/>');
  } },
  color: ['#b877d9', '#73bf69', '#f2cc0c', '#8e8e8e'],
  legend: { bottom: 0, data: Object.keys(colors), textStyle: { color: 'rgba(128, 128, 128, .9)' } },
  xAxis: { type: 'time', boundaryGap: false },
  yAxis: { type: 'value', name: 'Relative humidity (%)', nameLocation: 'middle', nameGap: 55, scale: true, minInterval: 0.5, axisLabel: { formatter: (value) => Number(value).toFixed(1) + '%' }, splitLine: { lineStyle: { color: 'rgba(128, 128, 128, .18)' } } },
  series: humiditySeries
};
